use std::io
use std::strings

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}
impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}
impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}
impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn main() {
    let mut shapes: Vec<Box<dyn Shape>> = []
    let mut line = ""
    while true {
        line = io::read_line() ?? ""
        if line.len() == 0 { break }
        let p = strings::split_whitespace(line)
        if p.len() == 0 { continue }
        let k = p[0]
        if k == "square" {
            shapes.push(Box::new(Square { s: p[1].parse::<int>() ?? 0 }))
        } else if k == "rect" {
            shapes.push(Box::new(Rect { w: p[1].parse::<int>() ?? 0, h: p[2].parse::<int>() ?? 0 }))
        } else if k == "rtri" {
            shapes.push(Box::new(Rtri { a: p[1].parse::<int>() ?? 0, b: p[2].parse::<int>() ?? 0 }))
        } else if k == "trap" {
            shapes.push(Box::new(Trap { a: p[1].parse::<int>() ?? 0, b: p[2].parse::<int>() ?? 0, h: p[3].parse::<int>() ?? 0 }))
        }
    }
    let mut total = 0
    let mut best = -1
    let mut bname = ""
    for s in shapes {
        let d = s.double_area()
        println("${s.name()} corners=${s.corners()} area2=${d}")
        total += d
        if d > best {
            best = d
            bname = s.name()
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${bname} area2=${best}")
    }
}

